ShaderBlob find_shader(const std::string& name) {
    if (name == "pointwise") return {k_pointwise, sizeof(k_pointwise) / sizeof(uint32_t)};
    if (name == "blur") return {k_blur, sizeof(k_blur) / sizeof(uint32_t)};
    if (name == "iir") return {k_iir, sizeof(k_iir) / sizeof(uint32_t)};
    if (name == "resample") return {k_resample, sizeof(k_resample) / sizeof(uint32_t)};
    if (name == "reduce") return {k_reduce, sizeof(k_reduce) / sizeof(uint32_t)};
    if (name == "expose") return {k_expose, sizeof(k_expose) / sizeof(uint32_t)};
    if (name == "develop") return {k_develop, sizeof(k_develop) / sizeof(uint32_t)};
    if (name == "grain") return {k_grain, sizeof(k_grain) / sizeof(uint32_t)};
    if (name == "spectral") return {k_spectral, sizeof(k_spectral) / sizeof(uint32_t)};
    if (name == "color") return {k_color, sizeof(k_color) / sizeof(uint32_t)};
    if (name == "encode") return {k_encode, sizeof(k_encode) / sizeof(uint32_t)};
    return {nullptr, 0};
}

